const enfermedadData=[{"disease":"Entraron probando claves toda la noche","characteristic":"Faltó el límite de intentos con espera creciente","opts":["Faltó el límite de intentos con espera creciente","Faltó la copia de seguridad","Faltó validar el formulario","Mala suerte"]},{"disease":"Supieron exactamente qué correos existían en la base","characteristic":"El mensaje de error distinguía los dos casos","opts":["El mensaje de error distinguía los dos casos","La clave era corta","No había copia","El servidor estaba lento"]},{"disease":"Con una sola tabla robada abrieron también los correos de la gente","characteristic":"Las claves estaban guardadas sin huella y sin sal, y la gente las repite","opts":["Las claves estaban guardadas sin huella y sin sal, y la gente las repite","Faltaba el doble factor del router","La tabla era muy grande","El diseño era antiguo"]},{"disease":"Un miembro borró filas de otro miembro","characteristic":"Faltó autorización por fila: menor privilegio","opts":["Faltó autorización por fila: menor privilegio","Faltó cifrar la pantalla","Faltó la sal","Faltó el registro de la impresora"]},{"disease":"El teléfono se cayó al agua y se perdió todo","characteristic":"No había copia: falló la disponibilidad","opts":["No había copia: falló la disponibilidad","Falló la confidencialidad","Falló la autenticación","Falló la validación"]},{"disease":"Alguien mandó su clave a un supuesto soporte","characteristic":"Phishing: la llave se le pidió a la persona, no al programa","opts":["Phishing: la llave se le pidió a la persona, no al programa","Un fallo del servidor","Un error de la copia","Una contraseña muy larga"]}];
let enferIdx=0,enferDone=false;
function showEnfer(){enferDone=false;if(enferIdx>=enfermedadData.length){const el=document.getElementById('enferDisease');if(el)el.textContent='🎉 ¡Completado!';const opts=document.getElementById('enferOpts');if(opts)opts.innerHTML='';return;}const d=enfermedadData[enferIdx];const prog=document.getElementById('enferProg');if(prog)prog.textContent=`${enferIdx+1} de ${enfermedadData.length}`;const dis=document.getElementById('enferDisease');if(dis)dis.textContent=d.disease;const opts=document.getElementById('enferOpts');if(!opts)return;opts.innerHTML='';_shuffle([...d.opts]).forEach(opt=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=opt;b.onclick=()=>checkEnfer(opt,b,d);opts.appendChild(b);});const fbEl=document.getElementById('fbEnfer');if(fbEl)fbEl.classList.remove('show');}
function checkEnfer(opt,btn,d){if(enferDone)return;enferDone=true;document.querySelectorAll('#enferOpts .qz-opt').forEach(b=>{if(b.textContent===d.characteristic)b.classList.add('correct');else if(b===btn&&b.textContent!==d.characteristic)b.classList.add('wrong');});const isOk=opt===d.characteristic;if(isOk){fb('fbEnfer','¡Correcto! +3 XP',true);if(!xpTracker.wgt.has('enfer_'+enferIdx)){xpTracker.wgt.add('enfer_'+enferIdx);pts(3);}sfx('ok');}else{fb('fbEnfer','Correcto: '+d.characteristic,false);sfx('no');}setTimeout(()=>{enferIdx++;showEnfer();},1800);}
function resetEnfer(){sfx('click');enferIdx=0;showEnfer();}

