const identifyTaskDB=[{"s":"El sistema responde «ese correo no existe».","type":"Mensaje que delata"},{"s":"La clave se guarda convertida en un resultado que no se puede devolver.","type":"Huella"},{"s":"Cada usuario tiene un texto al azar distinto mezclado con su clave.","type":"Sal"},{"s":"Tras cinco fallos el sistema espera, y la espera crece.","type":"Límite de intentos"},{"s":"Cada miembro solo puede leer y borrar sus propias filas.","type":"Menor privilegio"},{"s":"El servidor revisa el largo y el tipo de todo lo que llega.","type":"Validación"},{"s":"Hay tres copias, en dos lugares, y una fuera de la casa.","type":"Regla 3-2-1"},{"s":"Un mensaje con prisa pide la clave para «arreglar la cuenta».","type":"Phishing"}];
