const evalTFBank=[{"q":"Autenticación y autorización son lo mismo con distinto nombre.","a":false},{"q":"La identificación por sí sola no prueba nada.","a":true},{"q":"De una huella bien hecha se puede volver a sacar la contraseña.","a":false},{"q":"La sal hace que dos claves iguales guarden huellas distintas.","a":true},{"q":"Decir «ese correo no existe» ayuda al usuario y no tiene ningún costo.","a":false},{"q":"Un programa que prueba claves no se cansa como una persona.","a":true},{"q":"Validar en el formulario de la pantalla es suficiente.","a":false},{"q":"El menor privilegio dice que cada cuenta pueda hacer solo lo que necesita.","a":true},{"q":"Perder los datos también es un problema de seguridad.","a":true},{"q":"Una copia guardada en el mismo teléfono que el original sirve como copia.","a":false},{"q":"La clave de administración puede viajar dentro de la aplicación si está escondida.","a":false},{"q":"Con la seguridad por fila apagada, la clave pública permite borrar filas ajenas.","a":true},{"q":"El phishing ataca al programa, no a la persona.","a":false},{"q":"El doble factor sirve aunque roben la contraseña.","a":true},{"q":"Una regla de seguridad sin responsable funciona igual.","a":false}];
