function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Un familiar escribe por mensaje: \"Se me trabó la aplicación, mandame tu clave de F.A.R.O para entrar desde mi teléfono y revisarlo, es rapidito\"."},{"txt":"Se descubre que la clave del servicio de la nube quedó escrita dentro del código y ese repositorio estuvo público durante tres semanas."},{"txt":"Una escuela propone que M.E.T.A.S guarde nombres, grados y notas de sus 180 alumnos, y que los maestros entren con una sola cuenta compartida por grado."},{"txt":"Después de un fin de semana, aparecen 4.000 filas nuevas en la tabla de destellos, todas con texto sin sentido, escritas desde afuera."},{"txt":"El teléfono donde vive la aplicación familiar se pierde en una feria escolar, con la sesión abierta y sin clave de pantalla."},{"txt":"Un padre de familia reporta que entró a la plataforma con el correo de otro padre y vio las notas que no eran de su hijo."}];
const critCaseQuestions=["1. ¿Qué pieza de la puerta faltaba o falló, con su nombre exacto?","2. ¿Qué se puede perder aquí: se filtra, se pierde o se altera?","3. Escribe el arreglo más barato que de verdad sirve, en 3-4 frases.","4. ¿Qué regla de la casa hay que escribir para que no vuelva a pasar, y quién la responde?"];
const critCaseGuides=["Casi siempre falta una pieza con nombre propio: autenticación por persona, autorización por fila, límite de intentos, validación, separación del secreto o copia. Nombrarla es medio arreglo.","Distinguir los tres daños cambia la respuesta: lo que se filtra no se puede volver a esconder, lo que se pierde se recupera con copias, y lo que se altera necesita registro para siquiera notarlo.","El arreglo barato casi nunca es comprar algo: es una línea de mensaje, una regla por tabla, una espera creciente o una copia al mes. Si el arreglo propuesto cuesta dinero, casi seguro hay uno más simple antes.","Una regla sin responsable no es una regla. Debe decir qué se hace, quién lo hace y cada cuánto se revisa."];

const critErrorBank=[{"txt":"\"Como la aplicación es familiar y nadie la conoce, no hace falta cerrar nada\".","g1":"La seguridad por oscuridad no es seguridad: basta que la dirección se comparta una vez, o que alguien la encuentre, para que todo quede a la vista.","g2":"Y el costo no es técnico: es que se vean el chat, las finanzas y los datos de dos menores."},{"txt":"\"La clave está escondida dentro del programa, así que nadie la va a encontrar\".","g1":"Todo lo que viaja dentro de una aplicación se puede abrir y leer con herramientas comunes.","g2":"Un secreto que viaja no es secreto: hay que distinguir la clave pública, que puede viajar si las reglas están puestas, de la de administración, que nunca sale del servidor."},{"txt":"\"Guardo las claves tal como se escriben para poder ayudar a quien se le olvide\".","g1":"Poder ver la clave de alguien es exactamente el problema: si la puedes ver tú, la puede ver quien robe la tabla.","g2":"Lo correcto es no poder recuperarla nunca y ofrecer en su lugar un restablecimiento."},{"txt":"\"Ya validamos en la pantalla, así que el servidor puede confiar\".","g1":"La pantalla se puede saltar: los datos se pueden mandar directo al servidor sin pasar por el formulario.","g2":"La validación de la pantalla es comodidad para el usuario; la del servidor es la que protege."},{"txt":"\"Tenemos copia: está en el mismo teléfono, en otra carpeta\".","g1":"Una copia en el mismo aparato se pierde con el original: agua, robo o borrado se llevan las dos.","g2":"La regla 3-2-1 existe justamente por eso, y una copia que nunca se probó a restaurar no cuenta como copia."}];

const critDecisionBank=["Una escuela pide guardar nombres y notas de 180 menores en M.E.T.A.S: ¿con qué condiciones se acepta y qué datos NO se guardan?","La seguridad por fila lleva meses apagada para avanzar más rápido: ¿se enciende ahora o se sigue avanzando y se anota como deuda con fecha?","Un patrocinador ofrece pagar el hospedaje a cambio de que le den acceso de lectura a la base de datos: ¿qué se responde?","Se descubre que la clave de administración estuvo en un repositorio público tres semanas: ¿cuáles son los tres primeros pasos y en qué orden?","La familia quiere entrar sin escribir clave cada vez porque incomoda: ¿cómo se resuelve la comodidad sin abrir la puerta?","Una empresa ofrece «ponerle inteligencia artificial» a M.E.T.A.S gratis a cambio de los datos de uso de los estudiantes: ¿qué se cede y qué no?","El APK se va a compartir con tres maestros para que lo prueben: ¿qué se revisa antes de mandarlo?","Alguien de la casa perdió el teléfono con la sesión abierta: ¿qué se hace en la primera hora?"];
const critDecisionGuide="La decisión correcta sigue los principios de la casa: menos datos guardados es menos daño posible; lo que no se puede perder tiene copia probada; lo que puede filtrarse se cierra por fila y por persona; los secretos no viajan; y toda decisión que abre una puerta queda escrita, con fecha y con responsable. Cuando la comodidad choca con la seguridad, se busca la opción que no obligue a elegir (doble factor, sesión larga con bloqueo del teléfono) antes de bajar la guardia.";

const critCompareBank=[{"a":"Encender la seguridad por fila con una regla por tabla.","b":"Dejarla apagada y confiar en que nadie conoce la dirección.","ga":"Caso A: media hora de trabajo y desaparece el riesgo más grande que hoy tiene la casa; cada quien toca solo lo suyo.","gb":"Caso B: funciona hasta el día que la dirección se comparte una vez, y ese día se pierde todo de golpe, sin aviso."},{"a":"Un solo mensaje: «correo o contraseña incorrectos».","b":"Mensajes distintos para ayudar a quien se equivoca.","ga":"Caso A: cuesta una línea y le quita al atacante la mitad del trabajo, que es saber qué cuentas existen.","gb":"Caso B: es más cómodo para el usuario despistado, y regala el mapa de cuentas a cualquiera que pregunte."},{"a":"Cuenta por miembro con su propia clave.","b":"Una sola clave familiar compartida por todos.","ga":"Caso A: se sabe quién hizo qué, se puede quitar el acceso a uno solo y las niñas no ven lo que no les toca.","gb":"Caso B: es cómodo hoy y no hay forma de saber quién entró; si se filtra, se filtra para todos a la vez."},{"a":"Copia mensual de las tablas, con una fuera de la casa.","b":"Confiar en que la nube nunca falla.","ga":"Caso A: cuesta unos minutos al mes y salva años de finanzas, chat y progreso.","gb":"Caso B: la nube casi nunca falla, pero el borrado por error sí ocurre, y ahí no hay a quién reclamarle."},{"a":"Aceptar los datos de la escuela con permiso firmado y solo lo mínimo.","b":"Aceptar todos los datos que ofrezcan porque es buena tracción.","ga":"Caso A: menos datos guardados es menos daño posible, y el papel firmado dice quién responde.","gb":"Caso B: más datos de menores ajenos, sin permiso escrito, y el que responde si se filtran eres tú."}];

const critCauseBank=[{"cause":"Se comparte el archivo de instalación por mensaje con la clave adentro.","guide":"A partir de ahí el secreto está en manos desconocidas: hay que cambiar la clave, no explicarla, y separar el secreto del programa."},{"cause":"Se deja la seguridad por fila apagada para avanzar más rápido.","guide":"La deuda queda abierta: cualquiera con la clave pública lee y borra filas ajenas. Es aceptable mientras esté escrito y con fecha para arreglarlo, no como olvido."},{"cause":"Todos entran con la misma clave familiar.","guide":"Se pierde el rastro de quién hizo qué y no se le puede quitar el acceso a una sola persona sin cambiársela a toda la casa."},{"cause":"El sistema distingue «correo no existe» de «contraseña incorrecta».","guide":"El atacante obtiene la lista de cuentas válidas y concentra sus intentos solo en esas, que es el trabajo que le costaba caro."},{"cause":"No hay copia de las tablas de la nube.","guide":"Un borrado por error o una cuenta cerrada se lleva años de finanzas, chat y progreso, sin nadie a quien reclamar."},{"cause":"La familia nunca acordó por escrito qué hacer ante un mensaje raro.","guide":"Cada quien improvisa con prisa, que es justo la condición en la que el phishing funciona."}];
const critEffectBank=[{"effect":"Un intruso probó claves toda la noche y no consiguió entrar.","guide":"El límite de intentos con espera creciente hizo su trabajo: el ataque se volvió tan lento que dejó de valer la pena."},{"effect":"Se filtró la tabla de usuarios y aun así nadie pudo entrar a los correos de esas personas.","guide":"Las claves estaban guardadas como huella con sal: de la tabla no se pudo sacar ninguna clave utilizable."},{"effect":"Se perdió el teléfono y al día siguiente todo estaba de vuelta.","guide":"Había copia y estaba probada: la disponibilidad se protegió antes de necesitarla."},{"effect":"Una niña de la casa no pudo borrar los destellos de su mamá.","guide":"La autorización por fila estaba encendida: entrar a la casa no es entrar a todos los cuartos."},{"effect":"Nadie de la casa respondió al mensaje que pedía la clave.","guide":"La regla escrita funcionó: lo raro se pregunta en el chat familiar el mismo día, y nadie de soporte pide claves."},{"effect":"Se supo exactamente qué se tocó y desde cuándo tras un acceso extraño.","guide":"Había registro. Sin registro no se sabe qué pasó ni desde cuándo, y hay que asumir lo peor de todo."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Auditoría de la casa · Forma ${cf} · La puerta de la casa digital · Ruta de la Casa Cerrada`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué pieza de la puerta falta, qué se puede perder y cuál es el arreglo más barato que sirve? Explica por qué tu arreglo es mejor que no hacer nada o que comprar algo.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Qué protege cada caso y cuál aguanta el día que la dirección se comparta? 2. ¿Por qué no son el mismo caso?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Auditoría de la casa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué pieza de la puerta falta, qué se puede perder y cuál es el arreglo más barato que sirve? Explica por qué tu arreglo es mejor que no hacer nada o que comprar algo.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Qué protege cada caso y cuál aguanta el día que la dirección se comparta? 2. ¿Por qué no son el mismo caso?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Auditoría de la casa La puerta de la casa digital · Ruta de la Casa Cerrada · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Auditoría de la casa · La puerta de la casa digital · Ruta de la Casa Cerrada · Autocapacitación Técnica</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Auditoría de la casa · La puerta de la casa digital · Ruta de la Casa Cerrada · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🪪","label":"Identificación","text":"Quién dices que eres: el correo o el usuario. <strong>Qué hace:</strong> nombra la cuenta. <strong>Si falta:</strong> no se sabe de quién es cada dato. <strong>Hoy en casa:</strong> hay perfiles por miembro, pero se eligen tocando un chip, sin probar nada."},{"y":"2","icon":"🔑","label":"Autenticación","text":"Cómo pruebas que eres tú: clave, código al teléfono, huella digital. <strong>Si falta:</strong> cualquiera se hace pasar por cualquiera. <strong>Hoy en casa:</strong> el acceso es familiar y compartido, así que quien tenga la dirección y la clave entra como cualquiera de los cuatro."},{"y":"3","icon":"🚦","label":"Autorización","text":"Qué te dejan hacer adentro. <strong>Regla:</strong> menor privilegio, cada quien solo lo que necesita. <strong>Si falta:</strong> entrar a la casa es entrar a todos los cuartos. <strong>Hoy en casa:</strong> la seguridad por fila está apagada, así que esta pieza casi no existe."},{"y":"4","icon":"🧮","label":"Huella y sal","text":"La clave se guarda convertida en una huella que no se puede devolver, con una sal distinta por usuario. <strong>Si falta:</strong> quien robe la tabla tiene todas las claves y, como la gente las repite, también sus correos."},{"y":"5","icon":"⏱️","label":"Límite de intentos","text":"Después de varios fallos, el sistema espera, y la espera crece. <strong>Por qué:</strong> una persona se cansa a los cinco intentos y un programa prueba quinientos por minuto sin cansarse nunca."},{"y":"6","icon":"🧪","label":"Validación","text":"Todo lo que llega de afuera se revisa en el servidor: largo, tipo y forma. <strong>Por qué:</strong> el formulario de la pantalla se puede saltar. <strong>Si falta:</strong> aparecen cuatro mil filas basura un lunes por la mañana."},{"y":"7","icon":"💾","label":"Copia y registro","text":"Copias con la regla 3-2-1 y una bitácora de quién hizo qué. <strong>Por qué:</strong> perder también es perder, y sin registro no se sabe qué pasó ni desde cuándo. <strong>Prueba:</strong> una copia que nunca se restauró no es una copia."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(conInternet){sfx(conInternet?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(conInternet){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🛡️</span><span class="ms-text"><strong>Pediste 24 horas:</strong> la presión se corta en seco y la conversación pasa del sentimiento a los números.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📄</span><span class="ms-text"><strong>Al día siguiente decides tú:</strong> si el plazo era real, la oferta sigue en pie y ahora con condiciones tuyas. Si se cayó, la presión era el producto.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">✍️</span><span class="ms-text"><strong>Contestaste en caliente:</strong> el sí salió con la emoción alta y sin comparar nada.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔗</span><span class="ms-text"><strong>Y la coherencia lo amarra:</strong> ese sí pequeño se cobra después con uno más grande. No fue tonto: fue una decisión tomada en el peor momento posible.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"clave":{"nombre":"La clave","icon":"🔑","estructura":{"title":"Qué es","info":"• Lo que <strong>prueba</strong> que eres tú, no lo que dice quién eres<br>• Se guarda como <strong>huella con sal</strong>, nunca como texto<br>• Larga vence a complicada: una frase de cuatro palabras aguanta más que «P@l4nc0»"},"funcion":{"title":"Cómo funciona","info":"• Al registrarse se calcula la huella y se guarda solo eso<br>• Al entrar se vuelve a calcular y se comparan las dos huellas<br>• Nadie, ni el dueño del sistema, puede leer la clave original"},"enfermedades":{"title":"Cómo se rompe","info":"• Guardada en texto: una tabla robada las entrega todas<br>• Repetida en varios sitios: una filtración ajena abre tu casa<br>• Corta o predecible: cumpleaños, nombres y placas se prueban primero"},"cuidados":{"title":"En el proyecto","info":"• Una clave por persona en F.A.R.O, distinta de la del correo<br>• Nunca se manda por mensaje, ni a la familia<br>• Si se sospecha que se filtró: se cambia primero y se explica después"}},"mensaje":{"nombre":"El mensaje de error","icon":"🗣️","estructura":{"title":"Qué es","info":"• Lo que el sistema responde cuando alguien no logra entrar<br>• Parece cortesía y es <strong>información</strong><br>• Debe ser el mismo para los dos casos posibles"},"funcion":{"title":"Cómo funciona","info":"• «Correo o contraseña incorrectos» no distingue cuál falló<br>• El atacante no sabe si la cuenta existe<br>• Cuesta una línea de código y no cuesta nada de rendimiento"},"enfermedades":{"title":"Cómo se rompe","info":"• «Ese correo no existe»: confirma qué cuentas hay<br>• Tiempos de respuesta distintos: delatan lo mismo sin decirlo<br>• Errores técnicos completos en pantalla: enseñan cómo está hecho por dentro"},"cuidados":{"title":"En el proyecto","info":"• Es el arreglo más barato de toda la etapa<br>• Salió del destello del 27 de julio, punto 4<br>• Vale para F.A.R.O y para cualquier formulario de M.E.T.A.S"}},"limite":{"nombre":"El límite","icon":"⏱️","estructura":{"title":"Qué es","info":"• Un tope de intentos seguidos, con <strong>espera creciente</strong><br>• Protege contra la fuerza bruta, que es probar hasta acertar<br>• Se acompaña de un aviso cuando alguien insiste mucho"},"funcion":{"title":"Cómo funciona","info":"• Cinco fallos: unos segundos de espera<br>• Diez fallos: minutos<br>• La espera vuelve lento un ataque que era gratis, y lo hace dejar de valer la pena"},"enfermedades":{"title":"Cómo se rompe","info":"• Sin límite: quinientas claves por minuto, toda la noche<br>• Bloqueo permanente por usuario: sirve para dejar fuera al dueño<br>• Límite solo en la pantalla: se salta mandando los datos directo"},"cuidados":{"title":"En el proyecto","info":"• Va del lado del servidor, nunca solo en la aplicación<br>• Aviso al chat familiar cuando alguien insista mucho<br>• Con doble factor, el límite deja de ser la única defensa"}},"secreto":{"nombre":"La clave de servicio","icon":"🗝️","estructura":{"title":"Qué es","info":"• La llave con la que el programa habla con la nube<br>• Hay <strong>pública</strong> (puede viajar si las reglas están puestas) y <strong>de administración</strong> (nunca sale del servidor)<br>• Confundirlas es el error más caro de esta etapa"},"funcion":{"title":"Cómo funciona","info":"• La pública identifica al proyecto, no autoriza por sí sola<br>• Las reglas por fila son las que deciden qué se puede tocar<br>• La de administración se salta todas las reglas: por eso no viaja"},"enfermedades":{"title":"Cómo se rompe","info":"• Clave de administración dentro del APK o del repositorio<br>• Clave pública con la seguridad por fila apagada: equivale a dar todo<br>• Clave filtrada y no rotada: sigue abierta meses después"},"cuidados":{"title":"En el proyecto","info":"• Revisar qué clave viaja hoy en F.A.R.O y con qué reglas<br>• Si el repositorio fue público alguna vez, rotar la clave<br>• Regla de la casa: los secretos no entran al control de versiones"}}};
let labParte='clave',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente auditor en formación!','¡Cuidas bien la casa!','¡Guardián de la casa cerrada!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🏗️ ¡'+name+' completó la Etapa 1 de la Ruta de la Casa Cerrada (La puerta de la casa digital)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

// ===================== INIT =====================
